      7'd16: deadline = 4'd7;
      7'd17: deadline = 4'd1;
      7'd19: deadline = 4'd7;
      7'd20: deadline = 4'd2;
      7'd21: deadline = 4'd6;
      7'd22: deadline = 4'd7;
      7'd23: deadline = 4'd1;
      7'd25: deadline = 4'd7;
      7'd26: deadline = 4'd2;
      7'd27: deadline = 4'd6;
      7'd28: deadline = 4'd7;
      7'd29: deadline = 4'd1;
      7'd31: deadline = 4'd7;
      7'd32: deadline = 4'd2;
      7'd33: deadline = 4'd6;
      7'd34: deadline = 4'd7;
      7'd35: deadline = 4'd1;
      7'd37: deadline = 4'd7;
      7'd38: deadline = 4'd2;
      7'd39: deadline = 4'd6;
      7'd40: deadline = 4'd7;
      7'd41: deadline = 4'd1;
      7'd43: deadline = 4'd7;
      7'd44: deadline = 4'd2;
      7'd45: deadline = 4'd6;
      7'd46: deadline = 4'd7;
      7'd47: deadline = 4'd1;
      7'd49: deadline = 4'd7;
      7'd50: deadline = 4'd2;
      7'd51: deadline = 4'd6;
      7'd52: deadline = 4'd7;
      7'd53: deadline = 4'd1;
      7'd55: deadline = 4'd3;
      7'd56: deadline = 4'd4;
      7'd57: deadline = 4'd2;
      7'd58: deadline = 4'd7;
      7'd59: deadline = 4'd7;
      7'd60: deadline = 4'd1;
      7'd62: deadline = 4'd3;
      default: begin deadline = 4'd0; has_deadline = 1'b0; end
    endcase
  end
  reg [6:0] next_state;
  always @(*) begin
    next_state = astate;
    if (m_where[0]) next_state = 7'd1;
    if (m_where[1]) next_state = 7'd2;
    if (m_where[2]) next_state = 7'd3;
    if (m_where[3]) next_state = 7'd4;
    if (m_where[4]) next_state = 7'd7;
    if (m_where[5]) next_state = 7'd5;
    if (m_where[6]) next_state = 7'd8;
    if (m_where[7]) next_state = 7'd6;
    if (m_where[8]) next_state = 7'd9;
    if (m_where[9]) next_state = 7'd10;
    if (m_where[10]) next_state = 7'd13;
    if (m_where[11]) next_state = 7'd11;
    if (m_where[12]) next_state = 7'd14;
    if (m_where[13]) next_state = 7'd12;
    if (m_where[14]) next_state = 7'd15;
    if (m_where[15]) next_state = 7'd16;
    if (m_where[16]) next_state = 7'd19;
    if (m_where[17]) next_state = 7'd17;
    if (m_where[18]) next_state = 7'd20;
    if (m_where[19]) next_state = 7'd18;
    if (m_where[20]) next_state = 7'd21;
    if (m_where[21]) next_state = 7'd22;
    if (m_where[22]) next_state = 7'd25;
    if (m_where[23]) next_state = 7'd23;
    if (m_where[24]) next_state = 7'd26;
    if (m_where[25]) next_state = 7'd24;
    if (m_where[26]) next_state = 7'd27;
    if (m_where[27]) next_state = 7'd28;
    if (m_where[28]) next_state = 7'd31;
    if (m_where[29]) next_state = 7'd29;
    if (m_where[30]) next_state = 7'd32;
    if (m_where[31]) next_state = 7'd30;
    if (m_where[32]) next_state = 7'd33;
    if (m_where[33]) next_state = 7'd34;
    if (m_where[34]) next_state = 7'd37;
    if (m_where[35]) next_state = 7'd35;
    if (m_where[36]) next_state = 7'd38;
    if (m_where[37]) next_state = 7'd36;
    if (m_where[38]) next_state = 7'd39;
    if (m_where[39]) next_state = 7'd40;
    if (m_where[40]) next_state = 7'd43;
    if (m_where[41]) next_state = 7'd41;
    if (m_where[42]) next_state = 7'd44;
    if (m_where[43]) next_state = 7'd42;
