    if (m_where[52]) next_state = 7'd55;
    if (m_where[53]) next_state = 7'd56;
    if (m_where[54]) next_state = 7'd53;
    if (m_where[55]) next_state = 7'd57;
    if (m_where[56]) next_state = 7'd54;
    if (m_where[57]) next_state = 7'd58;
    if (m_where[58]) next_state = 7'd59;
    if (m_where[59]) next_state = 7'd62;
    if (m_where[60]) next_state = 7'd63;
    if (m_where[61]) next_state = 7'd60;
    if (m_where[62]) next_state = 7'd61;
  end
  always @(posedge clock) if (step) begin
    if (event_) begin astate <= next_state; since <= 4'd1; end
    else if (since != 4'd9) since <= since + 4'd1;
`ifdef SLOTS
    if (slot != 8'd224) slot <= slot + 8'd1;
`endif
    if (event_ && next_state == 7'd63) done <= 1'b1;
    if (event_ && next_state == 7'd6) fin_6 <= 1'b1;
    if (event_ && next_state == 7'd12) fin_12 <= 1'b1;
    if (event_ && next_state == 7'd18) fin_18 <= 1'b1;
    if (event_ && next_state == 7'd24) fin_24 <= 1'b1;
    if (event_ && next_state == 7'd30) fin_30 <= 1'b1;
    if (event_ && next_state == 7'd36) fin_36 <= 1'b1;
    if (event_ && next_state == 7'd42) fin_42 <= 1'b1;
    if (event_ && next_state == 7'd48) fin_48 <= 1'b1;
    if (event_ && next_state == 7'd54) fin_54 <= 1'b1;
    if (event_ && next_state == 7'd61) fin_61 <= 1'b1;
    if (event_ && next_state == 7'd63) fin_63 <= 1'b1;
  end
  // ---- properties ----
  always @(*) if (step) begin
    events: assert (!event_ || (m_where & m_gap) != 63'd0);
    levels: assert (event_ ? (m_where & m_level) != 63'd0 : (vis_a & VCH) == (vis_b & VCH));
    subslot: assert (event_ ? (m_where & m_sub) != 63'd0 : (sub_a[16] == out_a[4] && sub_a[17] == out_a[4] && sub_a[18] == out_a[4] && sub_a[19] == out_a[4] && sub_a[20] == out_a[5] && sub_a[21] == out_a[5] && sub_a[22] == out_a[5] && sub_a[23] == out_a[5]));
    deadline_: assert (!has_deadline || since <= deadline);
  end
  always @(*) if (past1 && phase != 2'd3) quiet: assert ((vis & VCH) == (vis_prev & VCH) && pin_sub[16] == pin_out[4] && pin_sub[17] == pin_out[4] && pin_sub[18] == pin_out[4] && pin_sub[19] == pin_out[4] && pin_sub[20] == pin_out[5] && pin_sub[21] == pin_out[5] && pin_sub[22] == pin_out[5] && pin_sub[23] == pin_out[5]);
  always @(*) if (fetch_t && started) page: assert (imem_addr[9:8] == T);
`ifdef SLOTS
  always @(*) if (step) slots: assert (!event_ || (m_where & m_slot) != 63'd0);
  always @(*) slots_ante: cover (done);
`endif
  // antecedents: the certificate's last state (state 63) is reached
  always @(*) events_ante: cover (done);
  always @(*) levels_ante: cover (done);
  always @(*) subslot_ante: cover (done);
  always @(*) deadline__ante: cover (done);
  always @(*) quiet_ante: cover (done);
  always @(*) page_ante: cover (done);
  always @(*) final_6: cover (fin_6);
  always @(*) final_12: cover (fin_12);
  always @(*) final_18: cover (fin_18);
  always @(*) final_24: cover (fin_24);
  always @(*) final_30: cover (fin_30);
  always @(*) final_36: cover (fin_36);
  always @(*) final_42: cover (fin_42);
  always @(*) final_48: cover (fin_48);
  always @(*) final_54: cover (fin_54);
  always @(*) final_61: cover (fin_61);
  always @(*) final_63: cover (fin_63);
  // the same as one negated assertion, for a bit-level BMC (abc bmc3): failing at step n is
  // reachable at step n. REACH names the signal (done, or fin_N)
`ifdef REACH
  always @(*) reach: assert (!`REACH);
`endif
